//! Embeds the Agent Skill's references (docs/agents/skills/compost/references,
//! generated by `just docs`) for `compost agent skill`, as `REFERENCES` in
//! `$OUT_DIR/references.rs`.

use std::fmt::Write as _;
use std::path::Path;
use std::{env, fs};

fn main() {
    let dir = Path::new(&env::var("CARGO_MANIFEST_DIR").unwrap())
        .join("docs/agents/skills/compost/references");
    println!("cargo::rerun-if-changed={}", dir.display());

    let mut names: Vec<String> = fs::read_dir(&dir)
        .map(|entries| {
            entries
                .map(|entry| entry.unwrap().file_name().into_string().unwrap())
                .filter(|name| name.ends_with(".md"))
                .collect()
        })
        .unwrap_or_default();
    names.sort();

    let mut code = String::from("&[\n");
    for name in names {
        let path = dir.join(&name);
        writeln!(code, "    ({name:?}, include_str!({:?})),", path.display()).unwrap();
    }
    code.push(']');
    fs::write(
        Path::new(&env::var("OUT_DIR").unwrap()).join("references.rs"),
        code,
    )
    .unwrap();
}
